"""Clinical syndromes (tier 0.5h).

Edit freely — see data/__init__.py for how files are loaded."""


_SYNDROMES = {
    'wernicke encephalopathy': 'Wernicke Encephalopathy — thiamine (B1) deficiency; classic triad: ophthalmoplegia (nystagmus, lateral gaze palsy), ataxia, confusion (only 10% have all 3); caused by alcoholism, hyperemesis gravidarum, malnutrition; tx: IV thiamine BEFORE glucose; can progress to Korsakoff if untreated',
    "wernicke's encephalopathy": 'Wernicke Encephalopathy — thiamine (B1) deficiency; classic triad: ophthalmoplegia, ataxia, confusion; tx: IV thiamine BEFORE glucose; MRI: mamillary body atrophy; can progress to Korsakoff (irreversible) if untreated',
    'korsakoff syndrome': "Korsakoff Syndrome — chronic irreversible thiamine deficiency; anterograde > retrograde amnesia + confabulation; follows untreated Wernicke's; mamillary body atrophy on MRI; minimal response to thiamine at this stage",
    "korsakoff's syndrome": "Korsakoff Syndrome — chronic irreversible thiamine deficiency; anterograde amnesia + confabulation; follows untreated Wernicke's; mamillary body atrophy on MRI",
    'osmotic demyelination syndrome': 'Osmotic Demyelination Syndrome (ODS) — demyelination from rapid correction of hyponatremia; central pontine myelinolysis (pons) ± extrapontine; presents: locked-in syndrome, dysarthria, dysphagia, spastic quadriplegia, pseudobulbar palsy; correct Na+ at ≤8 mEq/L per 24h; MRI: T2 hyperintensity in pons',
    'central pontine myelinolysis': 'Central Pontine Myelinolysis — see Osmotic Demyelination Syndrome; demyelination of pons from rapid hyponatremia correction; locked-in syndrome, dysarthria, quadriplegia; correct Na+ ≤8 mEq/L per 24h',
    'guillain-barre syndrome': 'Guillain-Barré Syndrome — acute post-infectious ascending demyelinating polyneuropathy; typically follows Campylobacter jejuni (most common), CMV, EBV, Zika; ascending flaccid paralysis + areflexia; CSF: albuminocytologic dissociation (↑protein, normal WBC); tx: IVIg or plasmapheresis; monitor FVC for respiratory failure',
    'lambert-eaton syndrome': 'Lambert-Eaton Myasthenic Syndrome — presynaptic NMJ disorder; anti-VGCC (voltage-gated Ca²⁺ channel) antibodies; paraneoplastic (SCLC most common); proximal muscle weakness that IMPROVES with repeated use (unlike MG); absent/diminished reflexes; autonomic dysfunction; tx: treat underlying cancer, 3,4-DAP',
    'brown-sequard syndrome': 'Brown-Séquard Syndrome — hemisection of spinal cord (stab wound, MS, tumor); ipsilateral: UMN weakness + loss of proprioception/vibration (dorsal column); contralateral: loss of pain/temperature (spinothalamic) 1-2 levels below lesion; best prognosis of spinal cord syndromes',
    'horner syndrome': 'Horner Syndrome — interruption of sympathetic chain; classic triad: ptosis (partial), miosis, anhidrosis; causes: Pancoast tumor (apical lung), carotid dissection (no anhidrosis), lateral medullary stroke (Wallenberg), syringomyelia; localize with cocaine/apraclonidine drops',
    'wallenberg syndrome': 'Wallenberg Syndrome (Lateral Medullary Syndrome) — PICA or vertebral artery occlusion; ipsilateral: facial pain/temp loss, Horner, ataxia, dysphagia; contralateral: body pain/temp loss; PICA mnemonic: PASTE (Pain-Ataxia-Sensory-Taste/dysphagia-Eye/Horner)',
    'cauda equina syndrome': 'Cauda Equina Syndrome — compression of lumbosacral nerve roots (L2-S5) below conus medullaris; saddle anesthesia, bowel/bladder dysfunction (urinary retention most common), bilateral leg weakness/numbness; SURGICAL EMERGENCY; MRI spine stat; most common cause: large central disc herniation at L4-L5 or L5-S1',
    'pancoast syndrome': 'Pancoast Syndrome — apical lung tumor (usually NSCLC) invading superior sulcus; Horner syndrome (ptosis, miosis, anhidrosis) + shoulder/arm pain radiating to ulnar aspect + ipsilateral upper extremity weakness/atrophy; rib/vertebral involvement possible',
    'svc syndrome': 'Superior Vena Cava Syndrome — obstruction of SVC; causes: lung cancer (NSCLC, SCLC), lymphoma, thrombosis (catheter-related); symptoms: facial/arm swelling, plethora, venous distension, headache (worse when bending forward), hoarseness; tx: treat underlying cause ± stenting',
    'dressler syndrome': 'Dressler Syndrome — post-cardiac injury syndrome; autoimmune pericarditis 2-10 weeks after MI, cardiac surgery, or trauma; fever, chest pain (pleuritic), pericardial/pleural effusion; tx: NSAIDs + colchicine; avoid anticoagulation if possible',
    'tamponade': "Cardiac Tamponade — fluid in pericardial space → ↑intrapericardial pressure → ↓CO; Beck's triad: hypotension + JVD + muffled heart sounds; pulsus paradoxus (>10 mmHg ↓SBP with inspiration); electrical alternans on ECG; tx: pericardiocentesis (emergency)",
    'cardiac tamponade': "Cardiac Tamponade — pericardial effusion → ↑intrapericardial pressure → ↓CO; Beck's triad: hypotension + JVD + muffled heart sounds; pulsus paradoxus >10 mmHg; electrical alternans on ECG; Kussmaul sign absent (unlike constrictive pericarditis); tx: emergency pericardiocentesis",
    'brugada syndrome': 'Brugada Syndrome — sodium channelopathy; type 1 ECG: coved-type ST elevation ≥2mm in V1-V2 with RBBB morphology (spontaneous or after sodium channel blocker); risk: sudden cardiac death from VF; male, Asian predominance; fever can unmask; tx: ICD; avoid flecainide/procainamide',
    'nephrotic syndrome': 'Nephrotic Syndrome — massive proteinuria (>3.5 g/day) + hypoalbuminemia + edema + hyperlipidemia + lipiduria (fatty casts, oval fat bodies); MCC adults: focal segmental glomerulosclerosis (FSGS) in Black patients, membranous nephropathy (others); MCC children: minimal change disease; complications: hypercoagulability (lose antithrombin III), infection',
    'nephritic syndrome': 'Nephritic Syndrome — hematuria (RBC casts) + proteinuria (<3.5 g/day) + HTN + oliguria + azotemia; causes: post-strep GN (children, ASO titer+, low C3), IgA nephropathy (macroscopic hematuria with URI), RPGN (crescentic GN, anti-GBM or ANCA), lupus nephritis',
    'hepatorenal syndrome': 'Hepatorenal Syndrome — functional AKI in setting of advanced liver disease/cirrhosis; HRS-AKI (formerly type 1; ICA criteria — AKI not improving after 48 h of diuretic withdrawal + albumin) vs HRS-CKD (formerly type 2); no alternative cause of AKI; kidneys are histologically normal; tx: terlipressin + albumin (FDA-approved 2022) or norepinephrine + albumin, liver transplant (definitive)',
    'bartter syndrome': 'Bartter Syndrome — defect in Na-K-2Cl transporter in TAL (like furosemide effect); hypokalemia + metabolic alkalosis + normal/low BP + ↑renin/aldosterone + ↑PGE2; salt wasting, polyuria; presents in childhood; tx: K+ supplementation, NSAIDs (↓PGE2), ACEi',
    'gitelman syndrome': 'Gitelman Syndrome — defect in Na-Cl cotransporter in DCT (like thiazide effect); hypokalemia + metabolic alkalosis + hypocalciuria + hypomagnesemia + normal/low BP; milder than Bartter, often incidental; tx: Mg + K supplementation',
    'liddle syndrome': 'Liddle Syndrome — gain-of-function mutation in ENaC (collecting duct); HTN + hypokalemia + metabolic alkalosis + ↓renin + ↓aldosterone; responds to amiloride/triamterene (NOT spironolactone); autosomal dominant',
    'fanconi syndrome': "Fanconi Syndrome — generalized proximal tubule dysfunction; phosphaturia, glycosuria (normal glucose), aminoaciduria, uricosuria, bicarbonaturia, RTA type 2; causes: multiple myeloma, Wilson's disease, tenofovir (HIV), galactosemia, lead poisoning; rickets/osteomalacia from phosphate wasting",
    'alport syndrome': 'Alport Syndrome — COL4A3/4/5 mutation (type IV collagen); affects GBM, cochlea, lens; triad: glomerulonephritis (hematuria, proteinuria, progressive CKD) + sensorineural hearing loss + ocular abnormalities (anterior lenticonus); X-linked (MCC) or AR; EM: thinning, thickening, splitting (basket-weave) of GBM',
    'goodpasture syndrome': 'Goodpasture Syndrome — anti-GBM antibodies attacking type IV collagen (kidney + lung); pulmonary-renal syndrome: rapidly progressive GN + pulmonary hemorrhage (hemoptysis); anti-GBM Abs on IF (linear IgG deposition); tx: plasmapheresis + cyclophosphamide + steroids; HLA-DR2 association',
    'budd-chiari syndrome': 'Budd-Chiari Syndrome — hepatic vein occlusion → hepatic congestion; causes: hypercoagulable states (polycythemia vera MCC, antiphospholipid syndrome, pregnancy), tumor invasion; acute: RUQ pain + ascites + hepatomegaly; chronic: cirrhosis pattern; caudate lobe hypertrophy (separate venous drainage); tx: anticoagulation, TIPS, liver transplant',
    'hepatopulmonary syndrome': 'Hepatopulmonary Syndrome — liver disease + intrapulmonary vascular dilations → hypoxemia; platypnea-orthodeoxia (hypoxemia and dyspnea worsen when upright, improve lying down — opposite of most pulmonary disease); Dx: contrast echo (bubble study) or Tc-MAA scan; tx: liver transplant',
    'zollinger-ellison syndrome': 'Zollinger-Ellison Syndrome — gastrinoma (usually duodenum/pancreas) → ↑↑gastrin → ↑acid → multiple PUD + diarrhea; check fasting gastrin (>1000 pg/mL with ↓pH diagnostic); secretin stimulation test (paradoxical ↑gastrin); 25% part of MEN1; tx: high-dose PPI, resection if possible',
    'gilbert syndrome': 'Gilbert Syndrome — benign UGT1A1 mutation; ↓glucuronidation → mild unconjugated hyperbilirubinemia (jaundice with fasting/illness/stress); normal LFTs, normal CBC; no treatment needed; most common hereditary hyperbilirubinemia (5-10% population)',
    'crigler-najjar syndrome': 'Crigler-Najjar Syndrome — severe UGT1A1 deficiency; type I (complete absence): severe unconjugated hyperbilirubinemia → kernicterus; requires phototherapy 12+ hrs/day; liver transplant curative; type II (partial deficiency): milder, responds to phenobarbital',
    'reye syndrome': 'Reye Syndrome — ASA use in children with viral illness (influenza, varicella) → mitochondrial dysfunction → microvesicular hepatic steatosis + encephalopathy; ↑ammonia, ↑LFTs, hypoglycemia, normal bilirubin; avoid ASA in children <18 with febrile illness',
    'meigs syndrome': 'Meigs Syndrome — benign ovarian fibroma (or thecoma) + ascites + right-sided pleural effusion (hydrothorax); ↑CA-125 (can mimic ovarian cancer); resolves completely after tumor removal; mechanism: transdiaphragmatic lymphatic flow',
    'conn syndrome': 'Conn Syndrome (Primary Hyperaldosteronism) — aldosterone-secreting adrenal adenoma (MCC) or bilateral hyperplasia; HTN + hypokalemia + metabolic alkalosis + ↓renin; dx: ↑aldosterone/renin ratio (>30) → CT adrenals → adrenal vein sampling; tx: adenoma → surgery; hyperplasia → spironolactone',
    'cushing syndrome': 'Cushing Syndrome — excess cortisol; causes: exogenous steroids (MCC), pituitary adenoma (Cushing disease, ACTH-dependent), adrenal adenoma (ACTH-independent), ectopic ACTH (SCLC); buffalo hump, moon facies, central obesity, purple striae, HTN, DM, hirsutism, osteoporosis; dx: 24h urine free cortisol, late-night salivary cortisol, low-dose dexamethasone suppression test',
    'cushing disease': 'Cushing Disease — pituitary ACTH-secreting adenoma → bilateral adrenal hyperplasia → ↑cortisol (ACTH-dependent); ↑ACTH suppresses with high-dose dexamethasone (distinguishes from ectopic ACTH); tx: transsphenoidal surgery; if not curable: bilateral adrenalectomy → Nelson syndrome',
    'addison disease': 'Addison Disease (Primary Adrenal Insufficiency) — destruction of adrenal cortex (autoimmune MCC in developed world, TB in developing); ↓cortisol + ↓aldosterone + ↑ACTH → hyperpigmentation; symptoms: fatigue, weakness, weight loss, nausea, hypotension, hyponatremia, hyperkalemia, hypoglycemia; dx: cosyntropin stimulation test; tx: hydrocortisone + fludrocortisone',
    "addison's disease": 'Addison Disease — primary adrenal insufficiency; autoimmune adrenal destruction (MCC); ↓cortisol + ↓aldosterone + ↑ACTH (hyperpigmentation); hyponatremia, hyperkalemia, hypoglycemia, hypotension; adrenal crisis: shock → hydrocortisone 100mg IV STAT',
    'men1': "MEN1 (Multiple Endocrine Neoplasia Type 1) — '3 P's': Pituitary adenoma (prolactinoma MCC) + Parathyroid hyperplasia/adenoma (HPT; MCC presentation) + Pancreatic tumors (gastrinoma MCC, insulinoma, VIPoma); autosomal dominant, MEN1 gene (tumor suppressor); tx: surgery for each component",
    'men2a': 'MEN2A (Multiple Endocrine Neoplasia Type 2A) — RET proto-oncogene mutation; Medullary thyroid carcinoma (MTC — virtually 100%; calcitonin marker) + Pheochromocytoma (50%) + Parathyroid hyperplasia (20-30%); tx: prophylactic total thyroidectomy in childhood (based on RET mutation risk level); screen/treat pheo BEFORE thyroid surgery',
    'men2b': 'MEN2B (Multiple Endocrine Neoplasia Type 2B) — RET mutation (codon 918); Medullary thyroid carcinoma (most aggressive) + Pheochromocytoma + Mucosal neuromas (lips, tongue, GI) + Marfanoid habitus; NO parathyroid involvement; prophylactic thyroidectomy in infancy',
    'carcinoid syndrome': 'Carcinoid Syndrome — symptoms from carcinoid tumor secreting serotonin (+ histamine, kallikrein) into systemic circulation; only when metastatic to liver (bypasses portal metabolism); DAFPN: Diarrhea, flushing, Abdominal pain/borborygmi, wheezing/bronchoconstriction, right-sided heart disease (tricuspid regurgitation); dx: ↑24h urine 5-HIAA; tx: octreotide (symptom control), resection',
    'marfan syndrome': 'Marfan Syndrome — FBN1 mutation (fibrillin-1); autosomal dominant; tall stature, arachnodactyly, arm span > height, ectopia lentis (lens subluxation upward), HIGH-arched palate, pectus excavatum/carinatum, scoliosis; cardiovascular: aortic root dilation → aortic regurgitation/dissection (MCC death), MVP; tx: BB (↓aortic root dilation), annual echo, avoid contact sports',
    'ehlers-danlos syndrome': 'Ehlers-Danlos Syndrome — collagen synthesis defect; hypermobile EDS (most common; gene unknown — clinical diagnosis): joint hypermobility, skin hyperextensibility; classical EDS (COL5A1/2): tissue fragility; vascular EDS (COL3A1): arterial/uterine/bowel rupture (life-threatening); dx: clinical + genetic; tx: symptomatic, avoid trauma',
    'neurofibromatosis type 1': 'Neurofibromatosis Type 1 (NF1/von Recklinghausen) — NF1 gene (neurofibromin, tumor suppressor); café-au-lait spots (≥6, >5mm prepubertal/>15mm adult) + neurofibromas + Lisch nodules (iris hamartomas) + axillary/inguinal freckling + optic glioma + osseous lesions; autosomal dominant; ↑risk: malignant peripheral nerve sheath tumors, leukemia',
    'neurofibromatosis type 2': 'Neurofibromatosis Type 2 (NF2) — NF2 gene (merlin/schwannomin); bilateral vestibular schwannomas (acoustic neuromas) → bilateral sensorineural hearing loss; + meningiomas, ependymomas, posterior subcapsular cataracts; autosomal dominant; dx: MRI IAC; tx: surgery or radiosurgery for schwannomas',
    'tuberous sclerosis': 'Tuberous Sclerosis Complex — TSC1/TSC2 mutations (hamartin/tuberin; mTOR pathway); HAMARTOMA mnemonic: cortical tubers (seizures), Ash-leaf spots, cardiac rhabdomyomas, Angiofibromas (adenoma sebaceum), renal angiomyolipomas, subependymal giant cell astrocytomas, pulmonary LAM; autosomal dominant with variable expressivity',
    'vhl disease': 'Von Hippel-Lindau Disease — VHL tumor suppressor gene mutation; hemangioblastomas (cerebellum, retina, spinal cord) + clear cell RCC + pheochromocytoma + pancreatic neuroendocrine tumors + endolymphatic sac tumors; autosomal dominant; annual surveillance with MRI/CT; tx: surgery/ablation for each lesion',
    'wilson disease': 'Wilson Disease — ATP7B mutation → impaired copper transport → copper accumulation; liver: hepatitis, cirrhosis; neuropsychiatric: dysarthria, tremor, personality change; Kayser-Fleischer rings (gold-brown corneal rings); ↓ceruloplasmin, ↑24h urine copper; dx: liver biopsy (gold standard); tx: D-penicillamine or trientine + zinc; liver transplant for fulminant',
    'hemochromatosis': 'Hereditary Hemochromatosis — HFE gene mutation (C282Y most common); ↑iron absorption → iron deposition; liver (cirrhosis), pancreas (bronze diabetes), skin (bronze), heart (cardiomyopathy, arrhythmias), joints (arthropathy, chondrocalcinosis), pituitary/gonads (hypogonadism); ↑transferrin saturation (>45%), ↑ferritin; dx: HFE genotyping ± liver biopsy; tx: phlebotomy',
    'antiphospholipid syndrome': 'Antiphospholipid Syndrome — autoimmune hypercoagulable state; antiphospholipid Abs: anticardiolipin (aCL), anti-β2-glycoprotein I, lupus anticoagulant; arterial and/or venous thrombosis + recurrent pregnancy loss; can be primary or associated with SLE; paradox: prolonged aPTT in vitro but thrombotic in vivo; tx: warfarin (DOACs inferior for APS); obstetric APS: LMWH + low-dose aspirin',
    'felty syndrome': 'Felty Syndrome — triad: RA + splenomegaly + neutropenia; occurs in long-standing seropositive RA; ↑risk of bacterial infections and lymphoma; ↑LGL (large granular lymphocytes); tx: MTX/DMARDs; G-CSF for severe neutropenia; splenectomy if refractory',
    'sjogren syndrome': 'Sjögren Syndrome — autoimmune exocrinopathy; anti-Ro/SSA + anti-La/SSB antibodies; primary vs secondary (associated with RA, SLE, scleroderma); dry eyes (keratoconjunctivitis sicca) + dry mouth (xerostomia) = sicca symptoms; extraglandular: arthritis, neuropathy, renal tubular acidosis, lymphoma (↑40x risk MALT); dx: lip biopsy (lymphocytic infiltrate), Schirmer test; tx: artificial tears, pilocarpine, hydroxychloroquine',
    'goodpasture disease': 'Goodpasture Disease — anti-GBM antibody disease (same as Goodpasture syndrome); linear IgG on IF; rapidly progressive GN + pulmonary hemorrhage; HLA-DR2; tx: emergency plasmapheresis + cyclophosphamide + corticosteroids',
    'lofgren syndrome': 'Löfgren Syndrome — acute sarcoidosis; classic triad: bilateral hilar adenopathy + erythema nodosum + polyarthritis/periarthritis (usually ankles); associated with anterior uveitis; good prognosis (>90% remit spontaneously); most common in Scandinavian and Irish women',
    'caplan syndrome': 'Caplan Syndrome — rheumatoid pneumoconiosis; RA + exposure to coal/silica/asbestos → large bilateral pulmonary nodules (1-5 cm) on CXR; radiographic findings disproportionate to respiratory symptoms; associated with positive RF',
    'raynaud phenomenon': 'Raynaud Phenomenon — episodic vasospasm of digital arteries triggered by cold or stress; color changes: white (pallor/ischemia) → blue (cyanosis) → red (reperfusion hyperemia); primary: idiopathic, young women, benign; secondary: connective tissue disease (scleroderma, SLE), arterial disease; tx: avoid triggers, CCBs (amlodipine), topical nitrates',
    'buerger disease': 'Buerger Disease (Thromboangiitis Obliterans) — non-atherosclerotic segmental inflammatory vasculitis of small/medium vessels; almost exclusively heavy smokers <45 years old; distal extremity ischemia → claudication → rest pain → digital ulcers/gangrene; dx: clinical; tx: SMOKING CESSATION (only effective treatment); amputation if needed',

    'digeorge syndrome': "DiGeorge Syndrome (22q11.2 deletion, velocardiofacial syndrome) — MCC: microdeletion chromosome 22q11.2 (TBX1 gene); mnemonic CATCH-22: Cardiac defects (conotruncal: ToF, truncus arteriosus, interrupted aortic arch, VSD, double outlet RV) + Abnormal facies + Thymic aplasia/hypoplasia (absent T cells → ↓cell-mediated immunity) + Cleft palate + Hypocalcemia (absent parathyroid → ↓PTH → tetany in neonates) + 22q11 deletion; variable expressivity; also: schizophrenia risk (30-fold ↑); learning disabilities; velopharyngeal insufficiency (hypernasal speech)",
    'williams syndrome': "Williams Syndrome — microdeletion chromosome 7q11.23 (ELN/elastin gene + ~26 genes); phenotype: supravalvular aortic stenosis (pathognomonic + other arterial stenoses) + intellectual disability + 'elfin' facies (periorbital puffiness, full cheeks, wide mouth, small chin) + hypercalcemia (↑sensitivity to vitamin D) + hypersocial/friendly personality ('cocktail party' personality) + excellent verbal/musical ability but poor visuospatial; mild-moderate ID; poor spatial reasoning; stellate iris pattern; hoarse voice",
    'mccardle disease': "McArdle Disease (GSD Type V) — AR; myophosphorylase deficiency (PYGM gene) → inability to break down muscle glycogen; symptoms: exercise intolerance, muscle cramps and weakness during isometric or aerobic exercise, myoglobinuria (dark urine) after exercise, rhabdomyolysis; 'second wind' phenomenon (pathognomonic): initial fatigue at exercise onset → rest → resumption at easier pace → symptoms improve as fatty acids/blood glucose substitute; ischemic forearm exercise test: ↑lactate failure to rise (blocks glycolysis) + ↑ammonia rises normally; treatment: sucrose before exercise, aerobic training",
    'kartagener syndrome': "Kartagener Syndrome (Primary Ciliary Dyskinesia) — AR; structural/functional defect of cilia (dynein arms — most common DNAI1, DNAH5 mutations); triad: situs inversus (50% of PCD — Kartagener) + bronchiectasis + chronic sinusitis; immotile cilia → recurrent RTIs → bronchiectasis; male infertility (immotile sperm); female infertility (fallopian tube cilia); diagnosis: nasal nitric oxide (low — PCD screening test), TEM of cilia (dynein arm absence), genetic testing; neonates: respiratory distress (meconium clearance needs cilia); treatment: airway clearance, antibiotics for exacerbations",
    'mallory-weiss syndrome': "Mallory-Weiss Syndrome — longitudinal mucosal tears at GEJ from forceful vomiting/retching; preceded by vomiting → then hematemesis (classically AFTER retching, not concurrent); risk factors: alcohol abuse, eating disorders, any severe vomiting; accounts for 5-15% of upper GI bleeds; usually stops spontaneously (80-90%); diagnosis: endoscopy (linear mucosal tears on gastric side of GEJ); distinguish from Boerhaave syndrome (transmural esophageal rupture — Mackler's triad: vomiting + chest pain + subcutaneous emphysema → mediastinitis → surgical emergency)",
    'lemierre syndrome': "Lemierre Syndrome — septic thrombophlebitis of internal jugular vein following oropharyngeal infection (Fusobacterium necrophorum, anaerobe); pathophysiology: peritonsillar/pharyngeal infection → lateral pharyngeal space → IJV thrombophlebitis → septic emboli to lungs (cavitary pneumonia) + other sites; young adults, previously healthy; classic presentation: pharyngitis → apparent improvement → recurrent fever, neck pain/swelling (IJV), pulmonary infiltrates/cavities; diagnosis: blood cultures (Fusobacterium), CT neck/chest (IJV thrombosis + lung nodules/cavities); treatment: prolonged antibiotics (metronidazole + beta-lactam), anticoagulation controversial but often used",
    'reiter syndrome': "Reactive Arthritis (formerly Reiter Syndrome) — sterile joint inflammation following genitourinary (Chlamydia trachomatis) or GI infection (Campylobacter, Salmonella, Shigella, Yersinia); classic triad: Can't see, Can't pee, Can't climb a tree (conjunctivitis + urethritis + arthritis); HLA-B27 associated; asymmetric oligoarthritis (lower > upper extremity) + sacroiliitis; skin: keratoderma blennorrhagica (psoriasis-like palms/soles), circinate balanitis; mouth ulcers; occurs weeks after infection; treatment: NSAIDs (first-line), antibiotics for active chlamydial infection, sulfasalazine/methotrexate for chronic disease",
    'sheehan syndrome': "Sheehan Syndrome — pituitary infarction/necrosis following postpartum hemorrhage and hypovolemic shock; pituitary enlarges during pregnancy (↑vascularity) → vulnerable to ischemia; adenohypophysis (anterior pituitary) > neurohypophysis; presents: failure to lactate (↓prolactin, first sign), loss of pubic/axillary hair, amenorrhea (↓FSH/LH), fatigue/cold intolerance (↓TSH → hypothyroidism), hypoglycemia (↓ACTH → cortisol deficiency); diagnosis: ↓pituitary hormones + low target organ hormones; MRI: empty sella; treatment: hormone replacement (hydrocortisone, thyroid, sex steroids), desmopressin if DI develops",
    'waterhouse-friderichsen syndrome': "Waterhouse-Friderichsen Syndrome — bilateral adrenal hemorrhage → acute adrenal crisis; classically associated with Neisseria meningitidis (meningococcemia), also DIC, septicemia (other organisms), anticoagulation; mechanism: overwhelming sepsis → DIC → adrenal vascular thrombosis → hemorrhagic infarction → cortisol deficiency; presents: rapidly progressive petechial/purpuric rash (non-blanching) + high fever + shock + adrenal crisis; adrenal enlargement with hemorrhage on CT; treatment: immediate hydrocortisone + antibiotics (ceftriaxone) + fluids; high mortality",
    'posterior reversible encephalopathy syndrome': "PRES (Posterior Reversible Encephalopathy Syndrome) — hypertensive emergency causing vasogenic cerebral edema predominantly in posterior (occipital/parietal) regions; mechanism: loss of cerebrovascular autoregulation → breakthrough hyperperfusion → endothelial dysfunction → vasogenic edema; causes: severe HTN, eclampsia/pre-eclampsia (MCC), immunosuppressants (cyclosporine, tacrolimus), chemotherapy; symptoms: headache, seizures, visual disturbances (cortical blindness), altered consciousness; MRI: T2/FLAIR hyperintensities in posterior regions (parieto-occipital); treatment: BP control, remove offending drug; usually reversible with treatment",
    'crush syndrome': "Crush Syndrome — systemic manifestation of prolonged muscle compression → rhabdomyolysis → myoglobinuric AKI; muscle ischemia → cell death → K+, myoglobin, phosphate, CK, uric acid released; myoglobin: precipitates in renal tubules (↑concentration at low pH) → tubular obstruction + direct toxicity → AKI; hyperkalemia (cardiac arrest risk), hypocalcemia (Ca2+ into necrotic muscle), hyperphosphatemia, hyperuricemia; reperfusion injury (fluid shifts to third space); treatment: aggressive IVF (NS or LR, high rate to maintain UO >200-300 mL/h) + urine alkalinization (sodium bicarb → prevents myoglobin precipitation) + monitor K+/Ca2+; dialysis if severe AKI",
    'serotonin syndrome': "Serotonin Syndrome — too much serotonergic activity within hours of a new drug, dose increase or combination (SSRIs/SNRIs + MAOIs, linezolid, tramadol, meperidine, triptans, dextromethorphan, ondansetron, St John’s wort, MDMA); triad: altered mental status (agitation), autonomic instability (hyperthermia, tachycardia, sweating, diarrhea, dilated pupils) and neuromuscular hyperactivity (CLONUS — inducible and ocular — and hyperreflexia, worse in the legs); Hunter criteria; tx: stop serotonergic drugs, benzodiazepines, cooling, cyproheptadine (5-HT2A antagonist), sedation/paralysis and intubation for severe hyperthermia; usually resolves within 24 h",
    'neuroleptic malignant syndrome': "Neuroleptic Malignant Syndrome — reaction to dopamine blockers (haloperidol and other antipsychotics, metoclopramide, prochlorperazine) or abrupt levodopa withdrawal; develops over days; FEVER + lead-pipe RIGIDITY + altered mental status + autonomic instability; ↑↑CK (rhabdomyolysis), leukocytosis, myoglobinuria → AKI; reduced reflexes (vs clonus in serotonin syndrome); tx: stop the drug, ICU supportive care, cooling, benzodiazepines, dantrolene and/or bromocriptine or amantadine for severe cases; 'FEVER': Fever, Encephalopathy, Vitals unstable, Elevated CK, Rigidity",
    'malignant hyperthermia': "Malignant Hyperthermia — autosomal dominant RYR1 (or CACNA1S) mutation → uncontrolled calcium release from the sarcoplasmic reticulum after volatile anesthetics (sevoflurane, desflurane, isoflurane) or succinylcholine; EARLIEST sign: rising end-tidal CO2, then tachycardia, masseter or generalized rigidity, hyperthermia (late), hyperkalemia, mixed acidosis, rhabdomyolysis; tx: stop the trigger, hyperventilate with 100% O2, IV DANTROLENE 2.5 mg/kg (repeat as needed), active cooling, treat hyperkalemia; susceptible patients need trigger-free anesthesia (propofol, nitrous oxide)",
    'tumor lysis syndrome': "Tumor Lysis Syndrome — release of cell contents after chemotherapy (or spontaneously) in bulky, fast-growing tumors (Burkitt lymphoma, ALL, AML with high WBC); ↑K+, ↑phosphate, ↑uric acid and secondary ↓calcium (calcium phosphate precipitates); AKI from uric acid and calcium phosphate crystals, arrhythmias, seizures; prevention: aggressive IV fluids + allopurinol (stops new uric acid) or rasburicase (breaks down existing uric acid — contraindicated in G6PD deficiency: hemolysis, methemoglobinemia); treat hyperkalemia; dialysis if refractory (Cairo-Bishop criteria)",
    'refeeding syndrome': "Refeeding Syndrome — dangerous fluid and electrolyte shifts when feeding restarts after starvation (anorexia nervosa, alcohol use disorder, prolonged NPO, cancer); the insulin surge drives phosphate, potassium and magnesium into cells → HYPOPHOSPHATEMIA (hallmark), hypokalemia, hypomagnesemia, thiamine deficiency (Wernicke), fluid retention; heart failure, arrhythmias, respiratory failure, rhabdomyolysis or seizures within 2–5 days; prevention: identify high-risk patients, start ~10–20 kcal/kg/day and increase slowly, give thiamine before feeding, check and replace phosphate, K+ and Mg2+ daily",
}
